            --text-color: #111827;
            --muted-text: #4b5563; /* Darker for better contrast */
            --border-color: #e5e7eb;
            --danger-color: #dc2626; /* Contrast 4.5:1 on white */
            --danger-hover: #b91c1c; /* Contrast > 4.5:1 on white */
            --surface-color: #ffffff;
            --btn-bg: #e5e7eb;
            --btn-hover: #d1d5db;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-color);
            margin: 0;
            padding: 2rem;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
