        .btn-delete:hover {
            background-color: var(--danger-color);
            color: white;
        }

        .btn-cancel {
            background-color: var(--btn-bg);
            color: var(--text-color);
            border: 1px solid transparent;
        }

        .btn-cancel:hover {
            background-color: var(--btn-hover);
        }

        .btn-confirm-delete {
            background-color: var(--danger-color);
            color: white;
            border: 1px solid transparent;
        }

        .btn-confirm-delete:hover {
            background-color: var(--danger-hover);
        }

        /* Dialog Styles */
        dialog {
            padding: 1.5rem;
            border: 1px solid var(--border-color);
            border-radius: 0.75rem;
            box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
            max-width: 400px;
            width: 90%;
            background-color: var(--surface-color);
            color: var(--text-color);
        }

        dialog::backdrop {
            background: rgba(0, 0, 0, 0.5);
            backdrop-filter: blur(2px);
        }

        dialog[open] {
            animation: show 0.2s ease-out normal;
        }

        @keyframes show {
            from {
                opacity: 0;
                transform: scale(0.95);
            }
            to {
                opacity: 1;
                transform: scale(1);
            }
        }

        .dialog-header {
            margin-top: 0;
            margin-bottom: 0.5rem;
            font-size: 1.25rem;
            font-weight: 600;
        }

        .dialog-body {
            color: var(--muted-text);
            margin-bottom: 1.5rem;
            font-size: 0.95rem;
            line-height: 1.5;
        }

        .dialog-footer {
            display: flex;
            justify-content: flex-end;
            gap: 0.75rem;
        }

        .sr-only {
            position: absolute;
            width: 1px;
            height: 1px;
            padding: 0;
            margin: -1px;
            overflow: hidden;
            clip: rect(0, 0, 0, 0);
            border: 0;
        }
    </style>
</head>
<body>

    <main class="preview-container">
        <h1 class="sr-only">Image Preview</h1>
        <!-- SVG used as informative graphic, therefore has role=img and aria-label -->
        <div class="image-placeholder" role="img" aria-label="Placeholder for image preview">
            <span>Image Preview</span>
        </div>

        <button type="button" class="trigger btn-delete" id="deleteImageBtn">Delete Image</button>
    </main>

    <!-- Dialog is closed by default, handles focus correctly natively -->
    <dialog id="deleteConfirmDialog" aria-labelledby="dialog-title" aria-describedby="dialog-desc">
        <h2 id="dialog-title" class="dialog-header">Delete Image?</h2>
        <p id="dialog-desc" class="dialog-body">
            Are you sure you want to delete this image from your library? This action cannot be undone.
        </p>
        <div class="dialog-footer">
            <!-- Ensure default focus lands on cancel to prevent accidental destructive actions -->
            <button type="button" class="btn-cancel" data-close autofocus>Cancel</button>
            <button type="button" class="btn-confirm-delete" data-confirm>Delete</button>
        </div>
    </dialog>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const triggerBtn = document.getElementById('deleteImageBtn');
            const dialog = document.getElementById('deleteConfirmDialog');
            const cancelBtn = dialog.querySelector('[data-close]');
            const confirmBtn = dialog.querySelector('[data-confirm]');

            // Open dialog
            triggerBtn.addEventListener('click', () => {
                dialog.showModal();
            });

            // Close dialog on cancel
            cancelBtn.addEventListener('click', () => {
                dialog.close('cancel');
            });

            // Close dialog on confirm
            confirmBtn.addEventListener('click', () => {
                // In a real application, perform the deletion here
                dialog.close('delete');
            });

            // Note: The browser natively restores focus to the trigger automatically on close
        });
    </script>
